 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(code!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null)return;if(req==OPEN){try{StringBuilder sb=new StringBuilder();try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);byte[] bytes=out.toByteArray();String s=new String(bytes,StandardCharsets.UTF_8);if(s.indexOf('\uFFFD')>=0)s=new String(bytes,"windows-1252");sb.append(s);}result=Engine.parse(sb.toString());fileName=uri.getLastPathSegment();choice=0;say("HISTÓRICO CARREGADO: "+result.records.size()+" concursos\nPrimeiro: "+result.records.get(0).contest+" | Último: "+result.records.get(result.records.size()-1).contest+"\nLinhas ignoradas: "+result.ignored+" | Concursos faltantes: "+result.gaps+"\nToque em ANALISAR.");}catch(Exception e){error(e);}}else if(req==SAVE){try{try(OutputStream out=getContentResolver().openOutputStream(uri)){writePdf(out);}say("PDF salvo com sucesso. Abra o arquivo na pasta escolhida.\n\n"+summary());}catch(Exception e){error(e);}}}
 void analyze(){if(result==null){say("Selecione o TXT/CSV primeiro.");return;}say("Analisando 300 duplas e 35 reinícios de otimização... Aguarde.");new Thread(()->{try{Engine.analyze(result,repeats);runOnUiThread(()->{if(result.top.isEmpty()){say("Nenhum jogo passou pelos filtros. Ajuste as repetidas.");return;}choice=0;say("ANÁLISE CONCLUÍDA em "+(result.elapsed/1000.0)+" s\n\n"+summary());});}catch(Exception e){runOnUiThread(()->error(e));}}).start();}
 void choose(){if(result==null||result.top==null||result.top.isEmpty()){say("Analise o histórico primeiro.");return;}int count=Math.min(5,result.top.size());String[] opts=new String[count];for(int i=0;i<count;i++){Engine.Candidate c=result.top.get(i);opts[i]=(i+1)+". "+Engine.numbers(c.mask)+"\nScore "+String.format(Locale.US,"%.3f",c.score);}new AlertDialog.Builder(this).setTitle("Escolha um conjunto de 10 falhas").setSingleChoiceItems(opts,choice,(d,w)->{choice=w;d.dismiss();say(summary());}).setNegativeButton("Cancelar",null).show();}
 void showGame(){if(result==null||result.top==null||result.top.isEmpty()){say("Analise o histórico primeiro.");return;}say(summary());}
 String summary(){if(result==null||result.top==null||result.top.isEmpty())return "Sem análise";Engine.Candidate c=result.top.get(choice);int[][] pairs=Engine.pairing(c.mask,result);StringBuilder s=new StringBuilder("LOTOFÁCIL CAMPEÃO V4\nHistórico: "+result.records.size()+" concursos\n\n5 DUPLAS CAMPEÃS:\n");for(int i=0;i<5;i++)s.append(i+1).append(". ").append(String.format(Locale.US,"%02d-%02d",pairs[i][0],pairs[i][1])).append('\n');s.append("\n10 PARA FALHA: ").append(Engine.numbers(c.mask)).append("\n15 PARA JOGAR: ").append(Engine.numbers(Engine.FULL^c.mask));int[] m=Engine.metrics(Engine.FULL^c.mask,result.lastDraw);s.append("\n\nFILTROS: repetidas ").append(m[0]).append(" | primos ").append(m[1]).append(" | Fibonacci ").append(m[2]).append(" | borda ").append(m[3]).append(" | miolo ").append(m[4]).append(" | pares ").append(m[5]).append(" | soma ").append(m[6]);int[] hist=Engine.hist(c.mask,result);s.append("\n\nHISTÓRICO DE FALHAS:\n");for(int i=5;i<=10;i++)s.append(i).append(" falhas: ").append(hist[i]).append(" concursos\n");s.append("\nTOP 5 CONJUNTOS:\n");for(int i=0;i<Math.min(5,result.top.size());i++)s.append(i+1).append(". ").append(Engine.numbers(result.top.get(i).mask)).append(" | ").append(String.format(Locale.US,"%.2f",result.top.get(i).score)).append('\n');return s.toString();}
